  "cotDisaggName": "Desagregado",
  "cotDisaggDesc": "Divide las materias primas en productores/comerciantes, swap dealers, dinero gestionado y otros declarables para mayor detalle.",
  "cotTffName": "Operadores en Futuros Financieros (TFF)",
